import re

def entities(doc, scope) -> list:
    """
    Every distinct entity the scope's records are about, with its full human-readable description.
    """
    node = node_by_title(doc, f"{scope}: Objects")
    ents = []
    for line in node.lines:
        # Example: 'Object 0: brown metal sphere (color=brown, material=metal, shape=sphere)'
        match = re.match(r'(Object \d+): ([^(\n]+)', line)
        if match:
            ents.append({
                "id": match.group(1),
                "description": match.group(2).strip()
            })
    return ents

def recorded_end(doc, scope) -> float:
    """
    The last time point covered by the scope's records.
    Each video is 128 frames (frame 0 to frame 127).
    """
    return 127.0

