def outcomes(doc, scope) -> list:
    """
    Every recorded event that results from the process (collisions, exits).
    """
    events_node = node_by_title(doc, f"{scope}: Events")
    outcomes_list = []

    for i, line in enumerate(events_node.lines):
        frame_match = re.search(r'Frame (\d+)', line)
        if not frame_match:
            continue

        frame = float(frame_match.group(1))

        if "collides with" in line:
            # Example: 'Frame 24: Object 0 (brown metal sphere) collides with Object 1 (cyan rubber sphere).'
            objs = re.findall(r'(Object \d+)', line)
            outcomes_list.append({
                "time": frame,
                "kind": "collision",
                "entities": objs,
                "value": None,
                "src": [events_node.node_id, i]
            })
        elif "exits the scene" in line:
            obj_match = re.search(r'(Object \d+)', line)
            if obj_match:
                outcomes_list.append({
                    "time": frame,
                    "kind": "exit",
                    "entities": [obj_match.group(1)],
                    "value": None,
                    "src": [events_node.node_id, i]
                })

    return outcomes_list

